import{n as S,q as P}from"./chunk-MNQC3QBW.js";import{Jb as h,Qa as a,W as y,Zb as t,_b as l,ac as D,db as v,ma as f,pc as g,qb as d,tb as b,vb as p,wb as m,xb as w,yb as n,zb as i}from"./chunk-PAGRJQTH.js";var z="2026-11-04";var u="\xA9 2026 M\u0103d\u0103lina-Eleonora Gheorghe",c="madalinaeleonora.gheorghe@gmail.com",x={title:"Privacy policy",intro:"DoseSync is built so that your health information stays on your phone. This policy explains what the app handles, where it is kept, what can leave your phone and what rights you have.",sections:[{heading:"Who is responsible",paragraphs:[`DoseSync is made by M\u0103d\u0103lina-Eleonora Gheorghe, an individual developer based in Romania. For anything about privacy, write to ${c}.`]},{heading:"The short version",paragraphs:["There is no account and no sign-up. DoseSync has no servers, no analytics, no advertising and no tracking. Your information is not sold or shared with anyone.","The developer cannot see what you enter in the app."]},{heading:"What the app keeps on your phone",paragraphs:["Medications and how to take them; the doses you take, skip or miss, with the reasons you choose; stock counts; menstrual cycle dates if you use them; appointments; and your settings.","Much of this is health information, a special category of personal data under Article 9 of the GDPR. You create it, it stays on your device, and it is used only to show your plan, remind you and keep your history.","If you set a PIN, only a scrambled form of it (a salted PBKDF2 hash) is stored, never the PIN itself."]},{heading:"How it is protected",paragraphs:["Your information is stored in an encrypted database (SQLCipher). The key is kept by Android in the phone\u2019s secure hardware (Android Keystore).","DoseSync is excluded from Android\u2019s cloud backup and from phone-to-phone transfer, so your health information is not copied to Google\u2019s servers.","You can add a PIN or fingerprint lock, and hide medication names in notifications for when others can see your screen."]},{heading:"When information leaves your phone",paragraphs:["Only when you choose to:",'Backup file. "Export backup" creates a file with all your DoseSync information and lets you choose where to save or send it. The file is not encrypted, so keep it somewhere safe.',"Feedback and contact. If you write to the developer from the About screen, your own email app sends the message. The developer then receives your email address and what you wrote, uses them only to reply and to improve DoseSync, and deletes them within two years, or sooner if you ask. The legal bases are answering your request (Article 6(1)(b) GDPR) and the legitimate interest of improving the app (Article 6(1)(f)). Please do not include health details you want to keep private; if you do, they are used only to answer you.","Links. The About screen links to Google Play, LinkedIn, the developer\u2019s website and, if shown, an optional donation page. They open outside DoseSync and their own privacy policies apply. The website counts visits with GoatCounter, without cookies and without collecting personal data."]},{heading:"Permissions on your phone",paragraphs:["Notifications: to remind you about doses, low stock and appointments.","Alarms and reminders (exact alarms): so reminders arrive on time.","Fingerprint or face: only if you turn on the lock. Android checks it; DoseSync never receives your fingerprint or face data.","Run at startup: so reminders are planned again after the phone restarts.","Internet: Android lists it because the app framework (Capacitor) declares it. DoseSync does not connect to the internet and does not send your information anywhere."]},{heading:"Google Play",paragraphs:["When you download DoseSync from Google Play, Google processes information about the download under its own privacy policy. The developer only sees anonymous totals from Google, such as the number of installs."]},{heading:"Children",paragraphs:["DoseSync is meant for adults. Children under 16 should use it together with a parent or guardian."]},{heading:"Your rights",paragraphs:['Everything in the app is in your hands: you can see and change it at any time, export it with "Export backup", and delete it by deleting items, or all of it by uninstalling DoseSync or clearing its data in Android settings. Deleted information cannot be recovered without a backup.',`For information the developer holds (feedback emails), you have the right to access, correct, delete, restrict, object to processing and receive a copy, and to withdraw consent at any time. Write to ${c}; you will get an answer within one month.`,"You can also complain to the Romanian data protection authority, ANSPDCP (www.dataprotection.ro), or to the authority in the EU country where you live."]},{heading:"Changes to this policy",paragraphs:["If this policy changes, the new version will appear in the app and on the developer\u2019s website with a new date. Important changes will be shown in the app before they apply."]}]},_={title:"Politica de confiden\u021Bialitate",intro:"DoseSync este construit astfel \xEEnc\xE2t informa\u021Biile tale de s\u0103n\u0103tate s\u0103 r\u0103m\xE2n\u0103 pe telefon. Aceast\u0103 politic\u0103 explic\u0103 ce gestioneaz\u0103 aplica\u021Bia, unde sunt p\u0103strate datele, ce poate pleca de pe telefon \u0219i ce drepturi ai.",sections:[{heading:"Cine este responsabil",paragraphs:[`DoseSync este creat de M\u0103d\u0103lina-Eleonora Gheorghe, dezvoltator independent din Rom\xE2nia. Pentru orice \xEEntrebare despre confiden\u021Bialitate, scrie la ${c}.`]},{heading:"Pe scurt",paragraphs:["Nu exist\u0103 cont \u0219i nici \xEEnregistrare. DoseSync nu are servere, nu folose\u0219te statistici, reclame sau urm\u0103rire. Informa\u021Biile tale nu sunt v\xE2ndute \u0219i nu sunt \xEEmp\u0103rt\u0103\u0219ite cu nimeni.","Dezvoltatorul nu poate vedea ce introduci \xEEn aplica\u021Bie."]},{heading:"Ce p\u0103streaz\u0103 aplica\u021Bia pe telefon",paragraphs:["Medicamentele \u0219i modul de administrare; dozele luate, s\u0103rite sau ratate, cu motivele alese de tine; cantit\u0103\u021Bile din sertar; datele ciclului menstrual, dac\u0103 le folose\u0219ti; program\u0103rile; \u0219i set\u0103rile tale.","Multe dintre acestea sunt date privind s\u0103n\u0103tatea, o categorie special\u0103 de date cu caracter personal conform articolului 9 din GDPR. Tu le creezi, ele r\u0103m\xE2n pe dispozitiv \u0219i sunt folosite doar pentru a-\u021Bi ar\u0103ta planul, a-\u021Bi aminti \u0219i a p\u0103stra istoricul.","Dac\u0103 setezi un PIN, se p\u0103streaz\u0103 doar o form\u0103 codificat\u0103 a lui (hash PBKDF2 cu sare), niciodat\u0103 PIN-ul \xEEnsu\u0219i."]},{heading:"Cum sunt protejate",paragraphs:["Informa\u021Biile tale sunt p\u0103strate \xEEntr-o baz\u0103 de date criptat\u0103 (SQLCipher). Cheia este p\u0103strat\u0103 de Android \xEEn hardware-ul securizat al telefonului (Android Keystore).","DoseSync este exclus din copiile de siguran\u021B\u0103 Android \xEEn cloud \u0219i din transferul \xEEntre telefoane, a\u0219a c\u0103 datele tale de s\u0103n\u0103tate nu sunt copiate pe serverele Google.","Po\u021Bi ad\u0103uga blocare cu PIN sau amprent\u0103 \u0219i po\u021Bi ascunde numele medicamentelor din notific\u0103ri, pentru c\xE2nd al\u021Bii \xEE\u021Bi pot vedea ecranul."]},{heading:"C\xE2nd pleac\u0103 informa\u021Bii de pe telefon",paragraphs:["Doar c\xE2nd alegi tu:","Fi\u0219ierul de copie. \u201EExport\u0103 copia\u201D creeaz\u0103 un fi\u0219ier cu toate informa\u021Biile din DoseSync \u0219i te las\u0103 s\u0103 alegi unde \xEEl salvezi sau cui \xEEl trimi\u021Bi. Fi\u0219ierul nu este criptat, a\u0219a c\u0103 p\u0103streaz\u0103-l \xEEntr-un loc sigur.","P\u0103reri \u0219i contact. Dac\u0103 \xEEi scrii dezvoltatorului din ecranul Despre, mesajul este trimis de propria ta aplica\u021Bie de e-mail. Dezvoltatorul prime\u0219te adresa ta de e-mail \u0219i ce ai scris, le folose\u0219te doar pentru a-\u021Bi r\u0103spunde \u0219i a \xEEmbun\u0103t\u0103\u021Bi DoseSync \u0219i le \u0219terge \xEEn cel mult doi ani sau mai devreme, dac\u0103 ceri. Temeiurile legale sunt r\u0103spunsul la solicitarea ta (articolul 6 alineatul (1) litera (b) din GDPR) \u0219i interesul legitim de a \xEEmbun\u0103t\u0103\u021Bi aplica\u021Bia (articolul 6 alineatul (1) litera (f)). Te rog s\u0103 nu incluzi detalii de s\u0103n\u0103tate pe care vrei s\u0103 le p\u0103strezi private; dac\u0103 o faci, sunt folosite doar pentru a-\u021Bi r\u0103spunde.","Linkuri. Ecranul Despre con\u021Bine linkuri c\u0103tre Google Play, LinkedIn, site-ul dezvoltatorului \u0219i, dac\u0103 apare, o pagin\u0103 op\u021Bional\u0103 de dona\u021Bii. Acestea se deschid \xEEn afara DoseSync \u0219i se aplic\u0103 propriile lor politici de confiden\u021Bialitate. Site-ul num\u0103r\u0103 vizitele cu GoatCounter, f\u0103r\u0103 cookie-uri \u0219i f\u0103r\u0103 a colecta date personale."]},{heading:"Permisiunile de pe telefon",paragraphs:["Notific\u0103ri: pentru mementouri despre doze, stoc sc\u0103zut \u0219i program\u0103ri.","Alarme \u0219i mementouri (alarme exacte): ca mementourile s\u0103 soseasc\u0103 la timp.","Amprent\u0103 sau fa\u021B\u0103: doar dac\u0103 activezi blocarea. Android face verificarea; DoseSync nu prime\u0219te niciodat\u0103 datele amprentei sau ale fe\u021Bei.","Pornire la deschiderea telefonului: ca mementourile s\u0103 fie replanificate dup\u0103 repornire.","Internet: Android o afi\u0219eaz\u0103 pentru c\u0103 platforma aplica\u021Biei (Capacitor) o declar\u0103. DoseSync nu se conecteaz\u0103 la internet \u0219i nu trimite informa\u021Biile tale nic\u0103ieri."]},{heading:"Google Play",paragraphs:["C\xE2nd descarci DoseSync din Google Play, Google prelucreaz\u0103 informa\u021Bii despre desc\u0103rcare conform propriei politici de confiden\u021Bialitate. Dezvoltatorul vede de la Google doar totaluri anonime, cum ar fi num\u0103rul de instal\u0103ri."]},{heading:"Copii",paragraphs:["DoseSync este destinat adul\u021Bilor. Copiii sub 16 ani ar trebui s\u0103 \xEEl foloseasc\u0103 \xEEmpreun\u0103 cu un p\u0103rinte sau tutore."]},{heading:"Drepturile tale",paragraphs:["Tot ce este \xEEn aplica\u021Bie este \xEEn m\xE2inile tale: po\u021Bi vedea \u0219i modifica oric\xE2nd, po\u021Bi exporta cu \u201EExport\u0103 copia\u201D \u0219i po\u021Bi \u0219terge elemente sau totul, dezinstal\xE2nd DoseSync sau \u0219terg\xE2nd datele aplica\u021Biei din set\u0103rile Android. Informa\u021Biile \u0219terse nu pot fi recuperate f\u0103r\u0103 o copie.",`Pentru informa\u021Biile pe care le de\u021Bine dezvoltatorul (e-mailurile cu p\u0103reri), ai dreptul de acces, rectificare, \u0219tergere, restric\u021Bionare, opozi\u021Bie \u0219i portabilitate, precum \u0219i dreptul de a-\u021Bi retrage oric\xE2nd consim\u021B\u0103m\xE2ntul. Scrie la ${c}; vei primi r\u0103spuns \xEEn cel mult o lun\u0103.`,"Po\u021Bi depune \u0219i o pl\xE2ngere la Autoritatea Na\u021Bional\u0103 de Supraveghere a Prelucr\u0103rii Datelor cu Caracter Personal, ANSPDCP (www.dataprotection.ro), sau la autoritatea din \u021Bara UE \xEEn care locuie\u0219ti."]},{heading:"Modific\u0103ri ale acestei politici",paragraphs:["Dac\u0103 politica se schimb\u0103, noua versiune va ap\u0103rea \xEEn aplica\u021Bie \u0219i pe site-ul dezvoltatorului, cu o dat\u0103 nou\u0103. Modific\u0103rile importante vor fi afi\u0219ate \xEEn aplica\u021Bie \xEEnainte s\u0103 se aplice."]}]},E={title:"Terms of use",intro:"These terms apply when you install or use DoseSync. Please read them; if you do not agree, do not use the app.",sections:[{heading:"Not medical advice",paragraphs:["DoseSync is a personal organiser for the plan you enter. It does not diagnose, treat or prevent any condition, and it does not recommend medications, doses or changes to your treatment.","Estimates such as the next period, when a medication runs out or what to pack for a trip are calculations from your own entries and may be wrong. Always follow your doctor\u2019s and pharmacist\u2019s instructions, and the leaflet of each medication.","In an emergency, call 112 or your local emergency number."]},{heading:"Your responsibilities",paragraphs:["Check that what you enter matches your prescription, and keep it up to date when your treatment changes.",'Keep notifications allowed for DoseSync, and make regular backups with "Export backup".',"Keep your phone, your PIN and your backup files safe."]},{heading:"Reminders can be late or missing",paragraphs:["Reminders depend on Android. Battery saving, phone settings, a switched-off or restarted phone, or a change of time zone can delay or stop them. Do not rely on DoseSync alone for medications where a missed or late dose could be dangerous."]},{heading:"Price and account",paragraphs:["DoseSync is free to use and does not need an account. Core features will not be put behind a payment."]},{heading:"Your information",paragraphs:["Your information stays on your phone, as explained in the privacy policy. If you uninstall the app, clear its data or lose your phone without a backup, the information cannot be recovered by anyone, including the developer."]},{heading:"Copyright and open-source components",paragraphs:[`${u}. DoseSync is free software: its source code is published under the GNU General Public License, version 3 or (at your option) any later version (GPL-3.0-or-later). You may use, study, share and change it under that license; anything built on it must stay under the same license.`,"The DoseSync name and logo are not covered by that license and may not be used for other apps without permission.","DoseSync includes open-source components, each used under its own license. The list and license texts are in the app under Settings \u2192 Privacy and terms \u2192 Open-source licenses."]},{heading:"No warranty",paragraphs:['DoseSync is provided "as is", without warranties of any kind, to the extent the law allows. The developer works to keep it accurate and reliable but cannot promise that it will always work without errors.']},{heading:"Limitation of liability",paragraphs:["To the extent the law allows, the developer is not liable for missed or wrong doses, lost information or other damage resulting from using DoseSync or from not being able to use it.","Nothing in these terms limits liability that cannot be limited by law, such as liability for intent or gross negligence, for harm to life or health caused by negligence, or your rights as a consumer."]},{heading:"Changes",paragraphs:["The app and these terms may change. The current version is always available in the app and on the developer\u2019s website, with its date. Important changes will be shown in the app before they apply. You can stop using DoseSync at any time by uninstalling it."]},{heading:"Applicable law",paragraphs:["These terms are governed by Romanian law. If you are a consumer living in another EU country, you keep the protection of the mandatory laws of that country."]},{heading:"Contact",paragraphs:[`Questions about these terms: ${c}.`]}]},T={title:"Termeni de utilizare",intro:"Ace\u0219ti termeni se aplic\u0103 atunci c\xE2nd instalezi sau folose\u0219ti DoseSync. Te rog s\u0103 \xEEi cite\u0219ti; dac\u0103 nu e\u0219ti de acord, nu folosi aplica\u021Bia.",sections:[{heading:"Nu este sfat medical",paragraphs:["DoseSync este un organizator personal pentru planul pe care \xEEl introduci. Nu diagnosticheaz\u0103, nu trateaz\u0103 \u0219i nu previne nicio afec\u021Biune \u0219i nu recomand\u0103 medicamente, doze sau modific\u0103ri ale tratamentului.","Estim\u0103rile, precum urm\u0103toarea menstrua\u021Bie, c\xE2nd se termin\u0103 un medicament sau ce s\u0103 iei \xEEntr-o c\u0103l\u0103torie, sunt calcule f\u0103cute din propriile tale date \u0219i pot fi gre\u0219ite. Urmeaz\u0103 mereu indica\u021Biile medicului \u0219i ale farmacistului \u0219i prospectul fiec\u0103rui medicament.","\xCEn caz de urgen\u021B\u0103, sun\u0103 la 112."]},{heading:"Responsabilit\u0103\u021Bile tale",paragraphs:["Verific\u0103 dac\u0103 ce introduci corespunde re\u021Betei \u0219i actualizeaz\u0103 datele c\xE2nd tratamentul se schimb\u0103.","P\u0103streaz\u0103 notific\u0103rile permise pentru DoseSync \u0219i f\u0103 regulat copii cu \u201EExport\u0103 copia\u201D.","P\u0103streaz\u0103 \xEEn siguran\u021B\u0103 telefonul, PIN-ul \u0219i fi\u0219ierele de copie."]},{heading:"Mementourile pot \xEEnt\xE2rzia sau lipsi",paragraphs:["Mementourile depind de Android. Economisirea bateriei, set\u0103rile telefonului, un telefon oprit sau repornit ori schimbarea fusului orar le pot \xEEnt\xE2rzia sau opri. Nu te baza doar pe DoseSync pentru medicamentele la care o doz\u0103 ratat\u0103 sau \xEEnt\xE2rziat\u0103 poate fi periculoas\u0103."]},{heading:"Pre\u021B \u0219i cont",paragraphs:["DoseSync este gratuit \u0219i nu necesit\u0103 cont. Func\u021Biile de baz\u0103 nu vor deveni contra cost."]},{heading:"Informa\u021Biile tale",paragraphs:["Informa\u021Biile tale r\u0103m\xE2n pe telefon, a\u0219a cum explic\u0103 politica de confiden\u021Bialitate. Dac\u0103 dezinstalezi aplica\u021Bia, \xEEi \u0219tergi datele sau pierzi telefonul f\u0103r\u0103 o copie, informa\u021Biile nu mai pot fi recuperate de nimeni, nici de dezvoltator."]},{heading:"Drepturi de autor \u0219i componente open-source",paragraphs:[`${u}. DoseSync este software liber: codul surs\u0103 este publicat sub Licen\u021Ba Public\u0103 General\u0103 GNU, versiunea 3 sau (la alegerea ta) orice versiune ulterioar\u0103 (GPL-3.0-or-later). \xCEl po\u021Bi folosi, studia, distribui \u0219i modifica \xEEn condi\u021Biile acestei licen\u021Be; orice lucrare construit\u0103 pe baza lui trebuie s\u0103 r\u0103m\xE2n\u0103 sub aceea\u0219i licen\u021B\u0103.`,"Numele \u0219i logoul DoseSync nu sunt acoperite de aceast\u0103 licen\u021B\u0103 \u0219i nu pot fi folosite pentru alte aplica\u021Bii f\u0103r\u0103 permisiune.","DoseSync include componente open-source, fiecare folosit\u0103 conform propriei licen\u021Be. Lista \u0219i textele licen\u021Belor se afl\u0103 \xEEn aplica\u021Bie, la Set\u0103ri \u2192 Confiden\u021Bialitate \u0219i termeni \u2192 Licen\u021Be open-source."]},{heading:"F\u0103r\u0103 garan\u021Bii",paragraphs:["DoseSync este oferit \u201Eca atare\u201D, f\u0103r\u0103 garan\u021Bii de niciun fel, \xEEn m\u0103sura permis\u0103 de lege. Dezvoltatorul se str\u0103duie\u0219te s\u0103 \xEEl p\u0103streze corect \u0219i fiabil, dar nu poate promite c\u0103 va func\u021Biona mereu f\u0103r\u0103 erori."]},{heading:"Limitarea r\u0103spunderii",paragraphs:["\xCEn m\u0103sura permis\u0103 de lege, dezvoltatorul nu r\u0103spunde pentru doze ratate sau gre\u0219ite, informa\u021Bii pierdute sau alte prejudicii rezultate din folosirea DoseSync ori din imposibilitatea de a-l folosi.","Nimic din ace\u0219ti termeni nu limiteaz\u0103 r\u0103spunderea care nu poate fi limitat\u0103 prin lege, cum ar fi r\u0103spunderea pentru inten\u021Bie sau culp\u0103 grav\u0103, pentru v\u0103t\u0103marea vie\u021Bii sau s\u0103n\u0103t\u0103\u021Bii din culp\u0103 ori drepturile tale de consumator."]},{heading:"Modific\u0103ri",paragraphs:["Aplica\u021Bia \u0219i ace\u0219ti termeni se pot schimba. Versiunea actual\u0103 este mereu disponibil\u0103 \xEEn aplica\u021Bie \u0219i pe site-ul dezvoltatorului, cu data ei. Modific\u0103rile importante vor fi afi\u0219ate \xEEn aplica\u021Bie \xEEnainte s\u0103 se aplice. Po\u021Bi \xEEnceta oric\xE2nd s\u0103 folose\u0219ti DoseSync, dezinstal\xE2ndu-l."]},{heading:"Legea aplicabil\u0103",paragraphs:["Ace\u0219ti termeni sunt guverna\u021Bi de legea rom\xE2n\u0103. Dac\u0103 e\u0219ti consumator \u0219i locuie\u0219ti \xEEn alt\u0103 \u021Bar\u0103 din UE, \xEE\u021Bi p\u0103strezi protec\u021Bia oferit\u0103 de legile obligatorii din acea \u021Bar\u0103."]},{heading:"Contact",paragraphs:[`\xCEntreb\u0103ri despre ace\u0219ti termeni: ${c}.`]}]},k={privacy:{en:x,ro:_},terms:{en:E,ro:T}};var A=(o,s)=>s.heading;function I(o,s){if(o&1&&(n(0,"p"),t(1),i()),o&2){let r=s.$implicit;a(),l(r)}}function M(o,s){if(o&1&&(n(0,"section")(1,"h2"),t(2),i(),p(3,I,2,1,"p",null,b),i()),o&2){let r=s.$implicit,e=s.$index;a(2),D("",e+1,". ",r.heading),a(),m(r.paragraphs)}}var G={en:"Last updated",ro:"Ultima actualizare"},C=class o{id=y(S).snapshot.data.document;language=f("en");document=g(()=>k[this.id][this.language()]);updated=g(()=>`${G[this.language()]}: ${z}`);otherDocument=this.id==="privacy"?{path:"/projects/dosesync/terms",label:"Terms of use"}:{path:"/projects/dosesync/privacy",label:"Privacy policy"};copyright=u;static \u0275fac=function(r){return new(r||o)};static \u0275cmp=v({type:o,selectors:[["app-dosesync-legal"]],decls:26,vars:9,consts:[[1,"legal"],[1,"eyebrow"],["role","group","aria-label","Language / Limba",1,"languages"],["type","button","lang","en",3,"click"],["type","button","lang","ro",3,"click"],[1,"updated"],[1,"intro"],[3,"routerLink"],["routerLink","/projects/dosesync"]],template:function(r,e){r&1&&(n(0,"article",0)(1,"header")(2,"span",1),t(3,"DoseSync"),i(),n(4,"h1"),t(5),i(),n(6,"div",2)(7,"button",3),h("click",function(){return e.language.set("en")}),t(8,"English"),i(),n(9,"button",4),h("click",function(){return e.language.set("ro")}),t(10,"Rom\xE2n\u0103"),i()(),n(11,"p",5),t(12),i(),n(13,"p",6),t(14),i()(),p(15,M,5,2,"section",null,A),n(17,"footer")(18,"p"),t(19),i(),n(20,"p")(21,"a",7),t(22),i(),t(23," \xB7 "),n(24,"a",8),t(25,"DoseSync case study"),i()()()()),r&2&&(d("lang",e.language()),a(5),l(e.document().title),a(2),d("aria-pressed",e.language()==="en"),a(2),d("aria-pressed",e.language()==="ro"),a(3),l(e.updated()),a(2),l(e.document().intro),a(),m(e.document().sections),a(4),l(e.copyright),a(2),w("routerLink",e.otherDocument.path),a(),l(e.otherDocument.label))},dependencies:[P],styles:["[_nghost-%COMP%]{display:block;width:100%;max-width:760px;margin:0 auto;padding:0 var(--page-gutter) var(--space-xl)}.legal[_ngcontent-%COMP%]{line-height:1.7}.legal[_ngcontent-%COMP%]   h1[_ngcontent-%COMP%]{margin:.25rem 0 .75rem}.legal[_ngcontent-%COMP%]   h2[_ngcontent-%COMP%]{margin:var(--space-lg) 0 .5rem;font-size:1.2rem}.legal[_ngcontent-%COMP%]   p[_ngcontent-%COMP%]{margin:0 0 .75rem}.eyebrow[_ngcontent-%COMP%]{color:var(--md-sys-color-primary);font-size:.8rem;font-weight:700;letter-spacing:.05rem;text-transform:uppercase}.languages[_ngcontent-%COMP%]{display:flex;gap:.5rem;margin-bottom:.75rem}.languages[_ngcontent-%COMP%]   button[_ngcontent-%COMP%]{min-height:44px;padding:0 1rem;border:1px solid var(--md-sys-color-outline-variant);border-radius:999px;background:transparent;color:inherit;font:inherit;font-weight:600;cursor:pointer}.languages[_ngcontent-%COMP%]   button[aria-pressed=true][_ngcontent-%COMP%]{border-color:var(--md-sys-color-primary);background:var(--md-sys-color-primary);color:var(--md-sys-color-on-primary)}.languages[_ngcontent-%COMP%]   button[_ngcontent-%COMP%]:focus-visible{outline:3px solid var(--md-sys-color-primary);outline-offset:2px}.updated[_ngcontent-%COMP%]{color:var(--md-sys-color-on-surface-variant);font-size:.9rem}.intro[_ngcontent-%COMP%]{font-size:1.1rem}footer[_ngcontent-%COMP%]{margin-top:var(--space-xl);padding-top:var(--space-md);border-top:1px solid var(--md-sys-color-outline-variant);color:var(--md-sys-color-on-surface-variant);font-size:.9rem}footer[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]{color:var(--md-sys-color-primary)}"],changeDetection:0})};export{C as DoseSyncLegal};
